-- READ ONLY after all statements; do NOT enable web writes yet.
USE auxiliares;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('FB_PERSONAS','FB_CIU_CONSULTAS_WEB','FB_CONTACTOS','FB_DOMICILIOS','FB_VINCULOS_DECLARADOS','FB_CONSULTAS_IDEMPOTENCIA') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,COLUMN_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND INDEX_NAME LIKE '%71%' OR (TABLE_SCHEMA=DATABASE() AND INDEX_NAME IN ('UK_FB_PERSONAS_DOCUMENTO','UK_FB_CONTACTOS_PERSONA','UK_FB_DOMICILIOS_PERSONA'));
SELECT TRIGGER_NAME,EVENT_OBJECT_TABLE,ACTION_TIMING,EVENT_MANIPULATION FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() ORDER BY TRIGGER_NAME;
SELECT COUNT(*) AS recibos_incompletos FROM FB_CONSULTAS_IDEMPOTENCIA WHERE ID_CONSULTA IS NULL;
